webpackJsonp([2],{FJCm:function(n,r){n.exports="---\n\n## 10. 对应的 PHP 命令行实现（两个版本）\n\n> 两个版本都实现同一件事：把已付款订单按 `(UTC 整点小时, 运营 owner_id)` 汇总写入 `gross_profit_stat_hour`。\n> 核心区别在**子查询是否携带订单级字段**：\n> - **版本 A**：子查询同时取出订单级字段，主查询 `fromSub` 直接使用子查询物化表，不再回 `platform_order`。\n> - **版本 B**：子查询只取 `order_id` 和商品金额，主查询 `joinSub` 回 `platform_order` 取订单字段。\n\n### 10.1 版本 A：子查询携带订单级字段，主查询 `fromSub`\n\n**特点：**\n\n- 子查询 `selectRaw` 包含 `owner_id`、`order_paid_at`、`currency_rate`、`purchase_cost_usd`、`shipping_cost_usd`；\n- 主查询 `Db::query()->fromSub($subQuery->toBase(), 'target_orders')`，不再扫 `platform_order`；\n- 注释说明“`platform_order` 只扫一遍”；\n- 默认 `--to` 当前是测试用 `$todayStart->modify('+1 day')`，上线前需改回 `$todayStart`。\n\n**完整脚本：**\n\n```php\n<?php\n\ndeclare(strict_types=1);\n\nnamespace App\\Command\\Report;\n\nuse App\\Enums\\Order\\IsProductComboEnum;\nuse App\\Enums\\Order\\OrderProductMatchStatusEnum;\nuse App\\Model\\Order\\GrossProfitStatHour;\nuse App\\Model\\Order\\PlatformOrder;\nuse App\\Model\\Order\\PlatformOrderProduct;\nuse DateTimeImmutable;\nuse DateTimeZone;\nuse Hyperf\\Command\\Annotation\\Command;\nuse Hyperf\\Command\\Command as HyperfCommand;\nuse Hyperf\\DbConnection\\Db;\nuse Symfony\\Component\\Console\\Input\\InputOption;\n\n/**\n * 毛利核算报表：把已付款订单按 (UTC 整点小时, 运营) 汇总写入 gross_profit_stat_hour\n *\n * 口径：\n *  - 订单量/采购成本/物流费直接取 platform_order（采购成本来自订单同步的明细行汇总，组合行已拆真实子SKU）\n *  - 销售额 USD = total_price × currency_rate（下单时快照的「订单货币→USD」，结算口径，不按报表汇率重算）\n *  - 汇率相关项（毛利公式中的 (订单量×2)/汇率、人民币毛利）不在此计算，由报表查询层按当日/区间平均汇率换算——除法不满足分配律，不能用小时值求和代替\n *  - 广告费不入表：求索会回填历史小时数据，报表查询时实时聚合 os 库，避免回填后数据丢失\n *\n * 按天 DELETE + INSERT 同事务覆盖，可任意重跑（订单成本回刷后重跑受影响时段即可），默认覆盖大前天 00:00 ~ 今天 00:00（UTC+8），共3天数据\n *\n * 执行：\n * php bin/hyperf.php report:gross-profit-stat-hour\n * 回刷历史：--from=2026-09-01 --to=2026-10-01（UTC+8 时间，支持 Y-m-d 或 Y-m-d H:i:s，但必须是整点）\n */\n#[Command]\nfinal class GrossProfitStatHourCommand extends HyperfCommand\n{\n    public function __construct()\n    {\n        parent::__construct('report:gross-profit-stat-hour');\n    }\n\n    public function configure(): void\n    {\n        $this->setDescription('按 (UTC小时, 运营) 汇总已付款订单到 gross_profit_stat_hour（毛利核算报表）');\n        $this->addOption('from', null, InputOption::VALUE_OPTIONAL, '起始时间(UTC+8，含，必须整点如 2026-09-01 08:00:00)，Y-m-d 或 Y-m-d H:i:s；默认大前天 00:00，共3天数据');\n        $this->addOption('to', null, InputOption::VALUE_OPTIONAL, '结束时间(UTC+8，不含，必须整点如 2026-09-02 00:00:00)；默认今天 00:00');\n        parent::configure();\n    }\n\n    public function handle(): int\n    {\n        // 解析时间段\n        $range = $this->getRange();\n        if ($range === null) {\n            return self::FAILURE;\n        }\n        [$fromLocal, $toLocal] = $range;\n\n        $this->output->writeln(sprintf(\n            '汇总区间(UTC+8)：%s ~ %s',\n            $fromLocal->format('Y-m-d H:i:s'),\n            $toLocal->format('Y-m-d H:i:s')\n        ));\n\n        $cursor = $fromLocal;\n        while ($cursor < $toLocal) {\n            $dayEnd = $cursor->modify('+1 day');\n            if ($dayEnd > $toLocal) {\n                $dayEnd = $toLocal;\n            }\n            // 统计毛利数据\n            $this->rebuildHourlyGrossProfitStats($cursor, $dayEnd);\n            $dayRows = GrossProfitStatHour::query()\n                ->where('stat_hour_utc', '>=', $this->toUtc($cursor))\n                ->where('stat_hour_utc', '<', $this->toUtc($dayEnd))\n                ->count();\n            $this->output->writeln(sprintf('  %s ~ %s：写入 %d 行', $cursor->format('Y-m-d H:i:s'), $dayEnd->format('Y-m-d H:i:s'), $dayRows));\n            $cursor = $dayEnd;\n        }\n        // 回显结果\n        $this->reportResult($fromLocal, $toLocal);\n\n        return self::SUCCESS;\n    }\n\n    /**\n     * UTC+8 时间转 UTC时间\n     */\n    private function toUtc(DateTimeImmutable $local): string\n    {\n        return $local->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');\n    }\n\n    /**\n     * 解析 [--from, --to) 区间，均为 UTC+8 整点时间；默认大前天 00:00 ~ 今天 00:00\n     * 只接受整点：按整点小时 DELETE + INSERT 覆盖写入\n     *\n     * @return array{0: DateTimeImmutable, 1: DateTimeImmutable}|null\n     * @throws \\DateMalformedStringException\n     */\n    private function getRange(): ?array\n    {\n        $timezone   = new DateTimeZone('Asia/Shanghai');\n        $todayStart = (new DateTimeImmutable('now', $timezone))->setTime(0, 0, 0);\n\n        $from = $this->parseTime((string)$this->input->getOption('from'), $todayStart->modify('-3 day'));\n        $to   = $this->parseTime((string)$this->input->getOption('to'), $todayStart);\n        if ($from === null || $to === null) {\n            return null;\n        }\n\n        foreach (['--from' => $from, '--to' => $to] as $option => $time) {\n            if ($time->format('i:s') !== '00:00') {\n                $this->output->writeln(sprintf(\n                    '<error>%s 必须是整点（分/秒为 00），当前 %s</error>',\n                    $option,\n                    $time->format('Y-m-d H:i:s')\n                ));\n                return null;\n            }\n        }\n\n        if ($from >= $to) {\n            $this->output->writeln('<error>--from 必须早于 --to</error>');\n            return null;\n        }\n\n        return [$from, $to];\n    }\n\n    /**\n     * 解析单个时间参数：支持 Y-m-d（按 00:00:00 处理）与 Y-m-d H:i:s，空值取默认\n     * 用回环校验严格拒绝 2026-13-45 这类被 DateTime 静默修正的输入\n     */\n    private function parseTime(string $value, DateTimeImmutable $default): ?DateTimeImmutable\n    {\n        $value = trim($value);\n        if ($value === '') {\n            return $default;\n        }\n\n        $timezone = new DateTimeZone('Asia/Shanghai');\n        foreach (['Y-m-d H:i:s', 'Y-m-d'] as $format) {\n            $parsed = DateTimeImmutable::createFromFormat('!' . $format, $value, $timezone);\n            if ($parsed instanceof DateTimeImmutable && $parsed->format($format) === $value) {\n                return $parsed;\n            }\n        }\n\n        $this->output->writeln(sprintf('<error>无法解析时间 \"%s\"（支持 Y-m-d 或 Y-m-d H:i:s）</error>', $value));\n\n        return null;\n    }\n\n    /**\n     * 小时毛利统计 统计该时间段内的数据：同事务内先删后插，可重复执行\n     *  - 把时间范围内的订单按照: UTC 整点小时 + 运营 owner_id 分组\n     *  - 销售额取百货商品行的分摊实付金额（platform_order_product.amount_rate_price，订单货币）× 订单汇率\n     *  - 百货口径：is_product_combo=1（组合商品一定是百货 SKU，且组合行恒为未匹配）或 match_status=1（已匹配百货 SKU）\n     *  - 非百货行 cost_price/weight 均为 0，故采购成本/物流费直接取订单级值即与「只算百货」等价\n     */\n    private function rebuildHourlyGrossProfitStats(DateTimeImmutable $fromLocal, DateTimeImmutable $toLocal): void\n    {\n        $utcFrom   = $this->toUtc($fromLocal);\n        $utcTo     = $this->toUtc($toLocal);\n        $localFrom = $fromLocal->format('Y-m-d H:i:s');\n        $localTo   = $toLocal->format('Y-m-d H:i:s');\n\n        Db::transaction(function () use ($utcFrom, $utcTo, $localFrom, $localTo) {\n            // 清空旧数据\n            GrossProfitStatHour::query()\n                ->where('stat_hour_utc', '>=', $utcFrom)\n                ->where('stat_hour_utc', '<', $utcTo)\n                ->delete();\n\n            // 子查询：百货商品行汇总 + 订单级字段一次性取出，platform_order 只扫一遍\n            //  - 借助 idx_paid_at 索引圈定时间窗口，JOIN platform_order_product（ref on idx_order_id）\n            //  - 子查询同时 SELECT 订单级字段（owner_id/order_paid_at/currency_rate/purchase_cost_usd/shipping_cost_usd），\n            //    主查询直接从子查询取值，不再回 platform_order 原表扫第二遍\n            //  - 百货口径：is_product_combo=1（组合商品一定是百货 SKU，且组合行恒为 match_status=2）\n            //    或 match_status=1（已匹配百货 SKU）；赠品 amount_rate_price=0 无需额外过滤\n            //  - 口径：窗口内没有任何百货行的订单会被 INNER JOIN 整单排除（含其订单级成本），属预期行为\n            $subQuery = PlatformOrder::query()\n                ->where('platform_order.order_paid_at', '>=', $localFrom)\n                ->where('platform_order.order_paid_at', '<', $localTo)\n                ->where('platform_order.owner_id', '>', 0)\n                ->join(PlatformOrderProduct::tableName(), 'platform_order.order_id', '=', 'platform_order_product.order_id')\n                ->where(function ($q) {\n                    $q->where('platform_order_product.is_product_combo', IsProductComboEnum::YES->value)\n                        ->orWhere('platform_order_product.match_status', OrderProductMatchStatusEnum::MATCHED->value);\n                })\n                ->selectRaw('platform_order.order_id')\n                ->selectRaw('platform_order.owner_id')\n                ->selectRaw('platform_order.order_paid_at')\n                ->selectRaw('platform_order.currency_rate')\n                ->selectRaw('platform_order.purchase_cost_usd')\n                ->selectRaw('platform_order.shipping_cost_usd')\n                ->selectRaw('SUM(platform_order_product.amount_rate_price) AS amount_local')\n                ->groupBy([\n                    'platform_order.order_id',\n                    'platform_order.owner_id',\n                    'platform_order.order_paid_at',\n                    'platform_order.currency_rate',\n                    'platform_order.purchase_cost_usd',\n                    'platform_order.shipping_cost_usd',\n                ]);\n\n            // 主查询：以子查询物化表为驱动，按 (UTC 小时, 运营) 聚合，不再扫 platform_order\n            $select = Db::query()->fromSub($subQuery->toBase(), 'target_orders')\n                ->selectRaw(\"DATE_FORMAT(CONVERT_TZ(target_orders.order_paid_at, '+08:00', '+00:00'), '%Y-%m-%d %H:00:00') AS stat_hour_utc\")\n                ->selectRaw('target_orders.owner_id AS user_id')\n                ->selectRaw('COUNT(*) AS order_count')\n                ->selectRaw('ROUND(SUM(target_orders.amount_local * target_orders.currency_rate), 2) AS sales_usd')\n                ->selectRaw('ROUND(SUM(target_orders.purchase_cost_usd), 2) AS purchase_cost_usd')\n                ->selectRaw('ROUND(SUM(target_orders.shipping_cost_usd), 2) AS shipping_cost_usd')\n                ->groupBy('stat_hour_utc', 'target_orders.owner_id');\n\n            // INSERT ... SELECT 避免在内存中处理写入\n            GrossProfitStatHour::query()->insertUsing(\n                ['stat_hour_utc', 'user_id', 'order_count', 'sales_usd', 'purchase_cost_usd', 'shipping_cost_usd'],\n                $select\n            );\n        });\n    }\n\n    /**\n     * 回显汇总结果\n     */\n    private function reportResult(DateTimeImmutable $fromLocal, DateTimeImmutable $toLocal): void\n    {\n        $utc     = new DateTimeZone('UTC');\n        $utcFrom = $fromLocal->setTimezone($utc)->format('Y-m-d H:i:s');\n        $utcTo   = $toLocal->setTimezone($utc)->format('Y-m-d H:i:s');\n\n        $base = GrossProfitStatHour::query()\n            ->where('stat_hour_utc', '>=', $utcFrom)\n            ->where('stat_hour_utc', '<', $utcTo);\n\n        $summary = (clone $base)\n            ->selectRaw('COUNT(*) AS hour_rows, COUNT(DISTINCT user_id) AS users, SUM(order_count) AS orders, ROUND(SUM(sales_usd), 2) AS sales, ROUND(SUM(purchase_cost_usd), 2) AS purchase, ROUND(SUM(shipping_cost_usd), 2) AS shipping')\n            ->first();\n\n        $this->output->writeln(sprintf('汇总完成，覆盖 %s ~ %s (UTC)', $utcFrom, $utcTo));\n\n        if ($summary === null || (int)$summary->hour_rows === 0) {\n            $this->output->writeln('<comment>区间内无已付款订单</comment>');\n            return;\n        }\n\n        $this->output->writeln(sprintf(\n            '  小时行 %d，运营 %d，订单 %s，销售 $%s，采购 $%s，物流 $%s',\n            $summary->hour_rows,\n            $summary->users,\n            $summary->orders,\n            $summary->sales,\n            $summary->purchase,\n            $summary->shipping\n        ));\n\n        $topUsers = (clone $base)\n            ->where('user_id', '<>', 0)\n            ->groupBy('user_id')\n            ->selectRaw('user_id, SUM(order_count) AS orders, ROUND(SUM(sales_usd), 2) AS sales')\n            ->orderByDesc('sales')\n            ->limit(5)\n            ->get();\n        foreach ($topUsers as $user) {\n            $this->output->writeln(sprintf('  user_id=%d：%s 单，销售 $%s', $user->user_id, $user->orders, $user->sales));\n        }\n    }\n}\n```\n\n---\n\n### 10.2 版本 B：子查询只取 `order_id + amount_local`，主查询 `joinSub` 回订单表\n\n**特点：**\n\n- 子查询只 `selectRaw('platform_order.order_id')` 和 `SUM(...) AS amount_local`，`GROUP BY platform_order.order_id`；\n- 主查询 `PlatformOrder::query()->joinSub($subQuery, 'target_orders', 'platform_order.order_id', '=', 'target_orders.order_id')`，回 `platform_order` 取订单字段；\n- 默认 `--to` 已恢复为 `$todayStart`；\n- 注释更详细，明确“非百货行 cost_price/weight 均为 0”“amount_rate_price 为订单货币金额”“赠品行”等口径。\n\n**完整脚本：**\n\n```php\n<?php\n\ndeclare(strict_types=1);\n\nnamespace App\\Command\\Report;\n\nuse App\\Enums\\Order\\IsProductComboEnum;\nuse App\\Enums\\Order\\OrderProductMatchStatusEnum;\nuse App\\Model\\Order\\GrossProfitStatHour;\nuse App\\Model\\Order\\PlatformOrder;\nuse App\\Model\\Order\\PlatformOrderProduct;\nuse DateTimeImmutable;\nuse DateTimeZone;\nuse Hyperf\\Command\\Annotation\\Command;\nuse Hyperf\\Command\\Command as HyperfCommand;\nuse Hyperf\\DbConnection\\Db;\nuse Symfony\\Component\\Console\\Input\\InputOption;\n\n/**\n * 毛利核算报表：把已付款订单按 (UTC 整点小时, 运营) 汇总写入 gross_profit_stat_hour\n *\n * 口径：\n *  - 仅统计窗口内「有百货行」的已付款订单；无任何百货行的订单会被 INNER JOIN 整单排除（含其订单级成本），属预期行为\n *  - 订单量/采购成本/物流费直接取 platform_order（采购成本来自订单同步的明细行汇总，组合行已拆真实子SKU）；\n *    非百货行 cost_price/weight 均为 0（数据前提），故取订单级值即与「只算百货」等价\n *  - 销售额 USD = SUM(百货行 platform_order_product.amount_rate_price，订单货币) × platform_order.currency_rate\n *    （amount_rate_price 为订单货币金额、非 USD；currency_rate 为下单时快照的「订单货币→USD」，结算口径，不按报表汇率重算）\n *  - 百货口径：is_product_combo=IsProductComboEnum::YES（组合商品一定是百货 SKU，且组合行恒为未匹配）\n *    或 match_status=OrderProductMatchStatusEnum::MATCHED（已匹配百货 SKU）\n *  - 排除 owner_id=0 的未分配运营订单\n *  - 时区前提：platform_order.order_paid_at 存储为 UTC+8 本地时间\n *  - 汇率相关项（毛利公式中的 (订单量×2)/汇率、人民币毛利）不在此计算，由报表查询层按当日/区间平均汇率换算——除法不满足分配律，不能用小时值求和代替\n *  - 广告费不入表：求索会回填历史小时数据，报表查询时实时聚合 os 库，避免回填后数据丢失\n *\n * 按天 DELETE + INSERT 同事务覆盖，可任意重跑（订单成本回刷后重跑受影响时段即可），默认覆盖大前天 00:00 ~ 今天 00:00（UTC+8），共3天数据\n *\n * 执行：\n * php bin/hyperf.php report:gross-profit-stat-hour\n * 回刷历史：--from=2026-09-01 --to=2026-10-01（UTC+8 时间，支持 Y-m-d 或 Y-m-d H:i:s，但必须是整点）\n */\n#[Command]\nfinal class GrossProfitStatHourCommand extends HyperfCommand\n{\n    public function __construct()\n    {\n        parent::__construct('report:gross-profit-stat-hour');\n    }\n\n    public function configure(): void\n    {\n        $this->setDescription('按 (UTC小时, 运营) 汇总已付款订单到 gross_profit_stat_hour（毛利核算报表）');\n        $this->addOption('from', null, InputOption::VALUE_OPTIONAL, '起始时间(UTC+8，含，必须整点如 2026-09-01 08:00:00)，Y-m-d 或 Y-m-d H:i:s；默认大前天 00:00，共3天数据');\n        $this->addOption('to', null, InputOption::VALUE_OPTIONAL, '结束时间(UTC+8，不含，必须整点如 2026-09-02 00:00:00)；默认今天 00:00');\n        parent::configure();\n    }\n\n    public function handle(): int\n    {\n        // 解析时间段\n        $range = $this->getRange();\n        if ($range === null) {\n            return self::FAILURE;\n        }\n        [$fromLocal, $toLocal] = $range;\n\n        $this->output->writeln(sprintf(\n            '汇总区间(UTC+8)：%s ~ %s',\n            $fromLocal->format('Y-m-d H:i:s'),\n            $toLocal->format('Y-m-d H:i:s')\n        ));\n\n        $cursor = $fromLocal;\n        while ($cursor < $toLocal) {\n            $dayEnd = $cursor->modify('+1 day');\n            if ($dayEnd > $toLocal) {\n                $dayEnd = $toLocal;\n            }\n            // 统计毛利数据\n            $this->rebuildHourlyGrossProfitStats($cursor, $dayEnd);\n            $dayRows = GrossProfitStatHour::query()\n                ->where('stat_hour_utc', '>=', $this->toUtc($cursor))\n                ->where('stat_hour_utc', '<', $this->toUtc($dayEnd))\n                ->count();\n            $this->output->writeln(sprintf('  %s ~ %s：写入 %d 行', $cursor->format('Y-m-d H:i:s'), $dayEnd->format('Y-m-d H:i:s'), $dayRows));\n            $cursor = $dayEnd;\n        }\n        // 回显结果\n        $this->reportResult($fromLocal, $toLocal);\n\n        return self::SUCCESS;\n    }\n\n    /**\n     * UTC+8 时间转 UTC时间\n     */\n    private function toUtc(DateTimeImmutable $local): string\n    {\n        return $local->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');\n    }\n\n    /**\n     * 解析 [--from, --to) 区间，均为 UTC+8 整点时间；默认大前天 00:00 ~ 今天 00:00\n     * 只接受整点：按整点小时 DELETE + INSERT 覆盖写入\n     *\n     * @return array{0: DateTimeImmutable, 1: DateTimeImmutable}|null\n     * @throws \\DateMalformedStringException\n     */\n    private function getRange(): ?array\n    {\n        $timezone   = new DateTimeZone('Asia/Shanghai');\n        $todayStart = (new DateTimeImmutable('now', $timezone))->setTime(0, 0, 0);\n\n        $from = $this->parseTime((string)$this->input->getOption('from'), $todayStart->modify('-3 day'));\n        $to   = $this->parseTime((string)$this->input->getOption('to'), $todayStart);\n        if ($from === null || $to === null) {\n            return null;\n        }\n\n        foreach (['--from' => $from, '--to' => $to] as $option => $time) {\n            if ($time->format('i:s') !== '00:00') {\n                $this->output->writeln(sprintf(\n                    '<error>%s 必须是整点（分/秒为 00），当前 %s</error>',\n                    $option,\n                    $time->format('Y-m-d H:i:s')\n                ));\n                return null;\n            }\n        }\n\n        if ($from >= $to) {\n            $this->output->writeln('<error>--from 必须早于 --to</error>');\n            return null;\n        }\n\n        return [$from, $to];\n    }\n\n    /**\n     * 解析单个时间参数：支持 Y-m-d（按 00:00:00 处理）与 Y-m-d H:i:s，空值取默认\n     * 用回环校验严格拒绝 2026-13-45 这类被 DateTime 静默修正的输入\n     */\n    private function parseTime(string $value, DateTimeImmutable $default): ?DateTimeImmutable\n    {\n        $value = trim($value);\n        if ($value === '') {\n            return $default;\n        }\n\n        $timezone = new DateTimeZone('Asia/Shanghai');\n        foreach (['Y-m-d H:i:s', 'Y-m-d'] as $format) {\n            $parsed = DateTimeImmutable::createFromFormat('!' . $format, $value, $timezone);\n            if ($parsed instanceof DateTimeImmutable && $parsed->format($format) === $value) {\n                return $parsed;\n            }\n        }\n\n        $this->output->writeln(sprintf('<error>无法解析时间 \"%s\"（支持 Y-m-d 或 Y-m-d H:i:s）</error>', $value));\n\n        return null;\n    }\n\n    /**\n     * 小时毛利统计：同事务内先删后插，可重复执行\n     *  - 仅统计窗口内「有百货行」的已付款订单，按 (UTC 整点小时, 运营 owner_id) 分组；\n     *    窗口内无任何百货行的订单会被 INNER JOIN 整单排除（含其订单级成本），属预期行为；\n     *    owner_id=0 的未分配运营订单排除\n     *  - 销售额 USD = SUM(百货行 amount_rate_price)（订单货币）× 订单 currency_rate\n     *  - 百货口径：is_product_combo=IsProductComboEnum::YES（组合行恒为未匹配，需单独放行）\n     *    或 match_status=OrderProductMatchStatusEnum::MATCHED（已匹配百货 SKU）\n     *  - 数据前提：非百货行 cost_price/weight 均为 0，故采购成本/物流费直接取订单级值即与「只算百货」等价；\n     *    amount_rate_price 为订单货币金额（非 USD），故需再乘 currency_rate\n     *  - 时区前提：order_paid_at 存储为 UTC+8 本地时间，CONVERT_TZ 转 UTC 后按整点小时归档\n     */\n    private function rebuildHourlyGrossProfitStats(DateTimeImmutable $fromLocal, DateTimeImmutable $toLocal): void\n    {\n        $utcFrom   = $this->toUtc($fromLocal);\n        $utcTo     = $this->toUtc($toLocal);\n        $localFrom = $fromLocal->format('Y-m-d H:i:s');\n        $localTo   = $toLocal->format('Y-m-d H:i:s');\n\n        Db::transaction(function () use ($utcFrom, $utcTo, $localFrom, $localTo) {\n            // 清空旧数据\n            GrossProfitStatHour::query()\n                ->where('stat_hour_utc', '>=', $utcFrom)\n                ->where('stat_hour_utc', '<', $utcTo)\n                ->delete();\n\n            // 百货商品行的分摊实付金额（订单货币），GROUP BY order_id → 1 单 1 行\n            //  - 百货口径：is_product_combo=IsProductComboEnum::YES（组合商品一定是百货 SKU，\n            //    且组合行恒为未匹配，故必须单独放行）或 match_status=OrderProductMatchStatusEnum::MATCHED（已匹配百货 SKU）\n            //  - owner_id > 0：排除未分配运营的订单，属统计口径\n            //  - 赠品：amount_price=0 → amount_rate_price=0，不影响销售额 SUM；\n            //    但若赠品行满足上述百货条件，仍会把订单带进子查询（计入 order_count 与订单级成本、销售额为 0），需业务确认是否符合预期\n            //  - 查询写法：用显式 JOIN 子查询而非「先查回 PHP 再 whereIn」——\n            //    不圈时间窗口时，优化器可能以 platform_order_product 为驱动表导致全表扫；\n            //    有 order_id 索引时 whereIn 字面量也能走 range，瓶颈不在扫表，\n            //    而在订单多时 SQL 体积膨胀（逼近 max_allowed_packet、解析与执行计划开销上升）且多一次查询往返，故聚合留在 SQL 内完成\n            //  - 口径：窗口内没有任何百货行的订单会被 INNER JOIN 整单排除（含其订单级成本），属预期行为\n            $subQuery = PlatformOrder::query()\n                ->join(PlatformOrderProduct::tableName(), 'platform_order.order_id', '=', 'platform_order_product.order_id')\n                ->where('platform_order.order_paid_at', '>=', $localFrom)\n                ->where('platform_order.order_paid_at', '<', $localTo)\n                ->where('platform_order.owner_id', '>', 0)\n                ->where(function ($q) {\n                    $q->where('platform_order_product.is_product_combo', IsProductComboEnum::YES->value)\n                        ->orWhere('platform_order_product.match_status', OrderProductMatchStatusEnum::MATCHED->value);\n                })\n                ->selectRaw('platform_order.order_id')\n                ->selectRaw('SUM(platform_order_product.amount_rate_price) AS amount_local')\n                ->groupBy('platform_order.order_id');\n\n            // 主查询 按 (UTC 小时, 运营) 聚合\n            //  - 子查询已按 order_id 聚合为 1 单 1 行，故 COUNT(*) 即订单数\n            //  - 假设 order_paid_at 存储为 UTC+8 本地时间，CONVERT_TZ 转 UTC 后按整点小时归档\n            //  - 非百货行 cost_price/weight 均为 0（数据前提），故订单级采购成本/物流费等价于「只算百货」\n            $select = PlatformOrder::query()->joinSub($subQuery, 'target_orders', 'platform_order.order_id', '=', 'target_orders.order_id')\n                ->selectRaw(\"DATE_FORMAT(CONVERT_TZ(platform_order.order_paid_at, '+08:00', '+00:00'), '%Y-%m-%d %H:00:00') AS stat_hour_utc\")\n                ->selectRaw('platform_order.owner_id AS user_id')\n                ->selectRaw('COUNT(*) AS order_count')\n                ->selectRaw('ROUND(SUM(target_orders.amount_local * platform_order.currency_rate), 2) AS sales_usd')\n                ->selectRaw('ROUND(SUM(platform_order.purchase_cost_usd), 2) AS purchase_cost_usd')\n                ->selectRaw('ROUND(SUM(platform_order.shipping_cost_usd), 2) AS shipping_cost_usd')\n                ->groupBy('stat_hour_utc', 'platform_order.owner_id');\n\n            // INSERT ... SELECT 避免在内存中处理写入\n            GrossProfitStatHour::query()->insertUsing(\n                ['stat_hour_utc', 'user_id', 'order_count', 'sales_usd', 'purchase_cost_usd', 'shipping_cost_usd'],\n                $select\n            );\n        });\n    }\n\n    /**\n     * 回显汇总结果\n     */\n    private function reportResult(DateTimeImmutable $fromLocal, DateTimeImmutable $toLocal): void\n    {\n        $utc     = new DateTimeZone('UTC');\n        $utcFrom = $fromLocal->setTimezone($utc)->format('Y-m-d H:i:s');\n        $utcTo   = $toLocal->setTimezone($utc)->format('Y-m-d H:i:s');\n\n        $base = GrossProfitStatHour::query()\n            ->where('stat_hour_utc', '>=', $utcFrom)\n            ->where('stat_hour_utc', '<', $utcTo);\n\n        $summary = (clone $base)\n            ->selectRaw('COUNT(*) AS hour_rows, COUNT(DISTINCT user_id) AS users, SUM(order_count) AS orders, ROUND(SUM(sales_usd), 2) AS sales, ROUND(SUM(purchase_cost_usd), 2) AS purchase, ROUND(SUM(shipping_cost_usd), 2) AS shipping')\n            ->first();\n\n        $this->output->writeln(sprintf('汇总完成，覆盖 %s ~ %s (UTC)', $utcFrom, $utcTo));\n\n        if ($summary === null || (int)$summary->hour_rows === 0) {\n            $this->output->writeln('<comment>区间内无已付款订单</comment>');\n            return;\n        }\n\n        $this->output->writeln(sprintf(\n            '  小时行 %d，运营 %d，订单 %s，销售 $%s，采购 $%s，物流 $%s',\n            $summary->hour_rows,\n            $summary->users,\n            $summary->orders,\n            $summary->sales,\n            $summary->purchase,\n            $summary->shipping\n        ));\n\n        $topUsers = (clone $base)\n            ->where('user_id', '<>', 0)\n            ->groupBy('user_id')\n            ->selectRaw('user_id, SUM(order_count) AS orders, ROUND(SUM(sales_usd), 2) AS sales')\n            ->orderByDesc('sales')\n            ->limit(5)\n            ->get();\n        foreach ($topUsers as $user) {\n            $this->output->writeln(sprintf('  user_id=%d：%s 单，销售 $%s', $user->user_id, $user->orders, $user->sales));\n        }\n    }\n}\n```\n\n---\n\n### 10.3 两个 PHP 版本与三种 SQL 写法的对应关系\n\n| PHP 版本 | 子查询内容 | 主查询方式 | 对应 SQL 写法 | 特点 |\n|---|---|---|---|---|\n| 版本 A | `order_id + 订单级字段 + amount_local`，`GROUP BY` 含订单级字段 | `fromSub($subQuery, 'target_orders')` | 接近写法一（订单先过滤 → JOIN 商品 → 按订单聚合），但订单字段在子查询里一次取出 | `platform_order` 只扫一遍；子查询 `GROUP BY` 字段多；主查询不再回订单表 |\n| 版本 B | 只取 `order_id + amount_local`，`GROUP BY order_id` | `joinSub($subQuery, 'target_orders', ...)` 回 `platform_order` | 接近写法二（商品先聚合 → JOIN 订单） | 子查询更简洁；`platform_order` 在子查询和外层各访问一次；外层通过 `uk_order_id` 回表 |\n\n**选择建议：**\n\n- 若 `platform_order` 时间窗过滤后订单量不大，**版本 B** 结构更简单，子查询只聚合商品金额，外层回表取订单字段，执行计划通常也稳定；\n- 若希望严格只扫一遍 `platform_order`，且能接受子查询 `GROUP BY` 字段较多，可用**版本 A**；\n- 两个版本最终写入 `gross_profit_stat_hour` 的结果在口径上一致，前提是 `order_id` 唯一、时间窗和 `owner_id` 条件一致；\n- 版本 A 当前默认 `--to` 是测试用 `todayStart->modify('+1 day')`，上线前记得改回 `$todayStart`。"},VgkB:function(n,r){n.exports="# MySQL SQL 优化实战指南\n\n> **适用场景**：接口变慢、慢查询日志出现新 SQL、上线前做 SQL 评审。\n> **核心原则**：先测量再优化 —— 没有执行计划和实测耗时的\"优化\"都是猜。\n\n## 目录\n\n- [1. 先定位：别凭感觉优化](#1-先定位别凭感觉优化)\n- [2. 读懂 EXPLAIN](#2-读懂-explain)\n- [3. 索引设计](#3-索引设计)\n- [4. 索引失效的常见写法](#4-索引失效的常见写法)\n- [5. 查询改写](#5-查询改写)\n- [6. 深分页优化](#6-深分页优化)\n- [7. JOIN、排序与分组](#7-join排序与分组)\n- [8. 表结构与数据类型](#8-表结构与数据类型)\n- [9. 写入优化与关键参数](#9-写入优化与关键参数)\n- [10. 实战案例：4.8s → 12ms](#10-实战案例48s--12ms)\n- [11. 上线前检查清单](#11-上线前检查清单)\n- [12. 容易踩的认知误区](#12-容易踩的认知误区)\n\n---\n\n## 1. 先定位：别凭感觉优化\n\n### 1.1 打开慢查询日志\n\n```ini\n[mysqld]\nslow_query_log                = ON\nslow_query_log_file           = /var/log/mysql/slow.log\nlong_query_time               = 1          # 单位秒，按业务容忍度调整\nmin_examined_row_limit        = 100        # 扫描行数少于 100 的不记录\nlog_queries_not_using_indexes = ON         # 注意：QPS 高时日志会暴涨，配合上面的参数用\nlog_output                    = FILE       # 设为 TABLE 则写入 mysql.slow_log 表\n```\n\n```sql\n-- 确认是否生效（改完可以 SET GLOBAL 临时生效，重启失效）\nSHOW VARIABLES LIKE 'slow_query_log%';\nSHOW VARIABLES LIKE 'long_query_time';\n\n-- log_output = TABLE 时可以直接查\nSELECT start_time, query_time, rows_examined, sql_text\nFROM mysql.slow_log\nORDER BY start_time DESC\nLIMIT 10;\n```\n\n### 1.2 从 performance_schema / sys 找问题 SQL\n\n```sql\n-- 全表扫描最多的语句\nSELECT * FROM sys.statements_with_full_table_scans LIMIT 10;\n\n-- 按总耗时排序，找出最该优化的 SQL\nSELECT digest_text,\n       count_star,\n       ROUND(avg_timer_wait / 1000000000, 2) AS avg_ms,\n       ROUND(sum_timer_wait / 1000000000, 2) AS total_ms\nFROM performance_schema.events_statements_summary_by_digest\nORDER BY sum_timer_wait DESC\nLIMIT 10;\n\n-- 正在跑的慢语句（大于 5 秒）\nSELECT id, user, time, state, LEFT(info, 120) AS sql_text\nFROM information_schema.processlist\nWHERE command <> 'Sleep' AND time > 5\nORDER BY time DESC;\n```\n\n### 1.3 日志分析工具\n\n```bash\n# 自带，按平均耗时归类\nmysqldumpslow -s at -t 20 /var/log/mysql/slow.log\n\n# Percona Toolkit，输出更详细（推荐）\npt-query-digest /var/log/mysql/slow.log\n```\n\n---\n\n## 2. 读懂 EXPLAIN\n\n```sql\nEXPLAIN SELECT id, amount, created_at\nFROM orders\nWHERE user_id = 123 AND status = 3\nORDER BY created_at DESC\nLIMIT 20;\n\n-- MySQL 8.0.18+：给出实际执行情况（真实行数、真实耗时），比 EXPLAIN 更可靠\nEXPLAIN ANALYZE SELECT ...;\n```\n\n| 字段 | 关注点 |\n| --- | --- |\n| `id` | 查询序号，id 越大越先执行；相同则从上往下 |\n| `select_type` | `SIMPLE` / `PRIMARY` / `SUBQUERY` / `DERIVED`（派生表，常见于子查询） |\n| `type` | **访问类型，最重要的指标**，见下表 |\n| `possible_keys` | 候选索引；为空说明没有可用索引 |\n| `key` | 实际用上的索引；和 `possible_keys` 不一致时说明选错了索引 |\n| `key_len` | 索引使用的字节数，能反推联合索引用到了前几列 |\n| `rows` | **预估**扫描行数，不是精确值（差一个数量级都可能） |\n| `filtered` | 走索引后剩余行数的百分比，越低说明索引过滤效果越差 |\n| `Extra` | 额外信息，重点看 `Using filesort` / `Using temporary` |\n\n`type` 从好到差：\n\n```\nsystem > const > eq_ref > ref > range > index > ALL\n```\n\n- `ref` / `range` 通常是及格线；\n- `index` 表示扫了整个索引树（比 `ALL` 强，但依然是大范围扫描）；\n- `ALL` 是全表扫描，大表上基本要处理。\n\n`Extra` 常见值：\n\n| 值 | 含义 |\n| --- | --- |\n| `Using index` | 覆盖索引，不需要回表，很好 |\n| `Using index condition` | 用上了索引下推（ICP，5.6+） |\n| `Using where` | 拿到行之后还要过滤，配合 `rows` 一起看 |\n| `Using filesort` | 需要额外排序；小结果集不一定是问题 |\n| `Using temporary` | 用了临时表，常见于无索引的 `GROUP BY` / `DISTINCT` / `UNION` |\n| `Using join buffer` | 被驱动表没有可用索引，用了 join buffer（8.0.18+ 可能是 hash join） |\n\n---\n\n## 3. 索引设计\n\n### 3.1 最左前缀\n\n联合索引 `idx(a, b, c)` 只能从最左列开始连续使用：\n\n| 查询条件 | 能否用上索引 |\n| --- | --- |\n| `a = ?` | ✅ 用到 a |\n| `a = ? AND b = ?` | ✅ 用到 a、b |\n| `b = ? AND c = ?` | ❌ 跳过了 a |\n| `a = ? AND c = ?` | ✅ 用到 a（c 只能靠 ICP 过滤，不能定位） |\n\n### 3.2 联合索引的列顺序\n\n一般遵循：**等值条件 → 范围条件 → 排序列**，等值条件里区分度高的靠前。\n\n```sql\n-- 查询：某用户已完成订单，按下单时间倒序取 20 条\nSELECT id, amount, created_at\nFROM orders\nWHERE user_id = 123 AND status = 3\nORDER BY created_at DESC\nLIMIT 20;\n\n-- 合适的索引：user_id、status 都是等值，created_at 用来排序\nALTER TABLE orders ADD INDEX idx_user_status_time (user_id, status, created_at);\n```\n\n注意：范围条件后面的列**不能用于定位**，只能用于过滤或覆盖。比如 `WHERE a = 1 AND b > 2 AND c = 3` 上建 `(a, b, c)`，`c` 就只能靠 ICP 过滤。\n\n### 3.3 覆盖索引\n\n查询需要的列都在索引里，就不用回表（Extra 显示 `Using index`）：\n\n```sql\n-- idx_user_status_time 已包含 user_id、status、created_at，主键 id 隐含在二级索引里\nEXPLAIN SELECT id, status, created_at FROM orders\nWHERE user_id = 123 AND status = 3 ORDER BY created_at DESC LIMIT 20;\n-- Extra: Using where; Using index  ← 没有回表\n\n-- 多查一个 amount 就需要回表；如果这条 SQL 是核心热点，可以考虑把 amount 也加进索引\nALTER TABLE orders ADD INDEX idx_cover (user_id, status, created_at, amount);\n```\n\n代价是索引变大、写入变慢，**不要为了覆盖而把所有列都塞进索引**。\n\n### 3.4 区分度（选择性）\n\n**区分度 = 不重复的值个数 ÷ 总行数**，越接近 1 越好。它决定的是「这个索引值不值得建」，是索引设计里最容易被忽略、又最影响结果的一步。\n\n```sql\n-- 先算候选列的区分度，再决定建不建\nSELECT COUNT(DISTINCT status)   / COUNT(*) AS status_sel,\n       COUNT(DISTINCT user_id)  / COUNT(*) AS user_id_sel,\n       COUNT(DISTINCT order_no) / COUNT(*) AS order_no_sel\nFROM orders;\n\n-- status_sel   = 0.0000004  （只有 5 个状态）→ 单独建索引没意义\n-- user_id_sel  = 0.31                        → 适合建（更适合进联合索引）\n-- order_no_sel = 1.0         （业务唯一）     → 最好的索引候选\n```\n\n经验判断（快速筛选用，最终还是要看 `EXPLAIN` 和实测耗时）：\n\n| 区分度 | 判断 | 处理方式 |\n| --- | --- | --- |\n| > 0.5 | 很好 | 单列索引就能过滤掉大部分数据 |\n| 0.1 ～ 0.5 | 一般 | 可以单独建，更推荐和其它列组成联合索引 |\n| 0.01 ～ 0.1 | 偏弱 | 别单独建；放进联合索引当配角，或做成覆盖索引 |\n| < 0.01（性别、状态、is_deleted） | 极弱 | 单独建索引基本不会被优化器选中 |\n\n**为什么低区分度单独建索引会\"建了也用不上\"**：假设 `status` 有 5 个值、表 1000 万行，查 `status = 1` 大约命中 200 万行。走二级索引要先扫这 200 万条索引记录，再回表 200 万次随机读；而全表扫描是顺序读。优化器算完成本后会直接选 `type: ALL` —— 不是索引坏了，是走索引更贵。\n\n**但有三个例外，别把结论用死：**\n\n1. **低区分度列放进联合索引仍然有用**。`(status, created_at)` 里 `status` 只把范围缩小到 1/5，但配合 `created_at` 的范围条件后能定位到很小区间；`(user_id, status)` 里 `status` 只是配角，作用是让等值条件被索引完全覆盖。\n\n2. **只取聚合值 / 覆盖索引时，低区分度索引也可能被选中**，因为索引比表窄、扫描代价更低：\n\n   ```sql\n   ALTER TABLE orders ADD INDEX idx_status (status);\n   EXPLAIN SELECT COUNT(*) FROM orders WHERE status = 1;\n   -- type: index（扫整个索引但不回表），Extra: Using where; Using index\n   ```\n\n3. **数据倾斜时平均区分度会骗人**。某列整体区分度很高，但个别值占了大部分数据（例如 `city` 里\"北京\"占 40%）：查热门值走索引反而更慢，查冷门值很快。这种情况 8.0 可以建直方图，让优化器知道真实分布：\n\n   ```sql\n   ANALYZE TABLE orders UPDATE HISTOGRAM ON city, status WITH 64 BUCKETS;\n   ```\n\n**联合索引的顺序怎么和区分度配合：**\n\n- 等值条件里，**区分度高的列放前面**；\n- 范围条件、排序列放后面（它们的位置由语义决定，不参与区分度排序）；\n- 不能只看单列的区分度，要看**组合后的区分度**：\n\n```sql\n-- status 单列区分度极低，但和 user_id 组合后完全够用\nSELECT COUNT(DISTINCT status, user_id) / COUNT(*) AS combo_sel,\n       COUNT(DISTINCT status)          / COUNT(*) AS status_sel\nFROM orders;\n```\n\n**`Cardinality` 是估算值，不能用它判断区分度：**\n\n```sql\nSHOW INDEX FROM orders;             -- 看 Cardinality 列（InnoDB 随机采样估算，偏差可能很大）\n\nSELECT * FROM information_schema.statistics   -- 同样的数据，方便批量对比\nWHERE table_schema = 'your_db' AND table_name = 'orders';\n\nANALYZE TABLE orders;               -- 统计信息过期会导致选错索引，可以手动刷新\n```\n\n评估「值不值得建索引」要用 `COUNT(DISTINCT)` 的真实值，不要拿 `SHOW INDEX` 的 `Cardinality` 当依据。\n\n**长字符串列建前缀索引时，也用区分度来挑长度：**\n\n```sql\n-- 找出\"能保留大部分区分度\"的最短前缀：p15 已接近全列区分度，就用 15\nSELECT COUNT(DISTINCT LEFT(email, 5))  / COUNT(*) AS p5,\n       COUNT(DISTINCT LEFT(email, 10)) / COUNT(*) AS p10,\n       COUNT(DISTINCT LEFT(email, 15)) / COUNT(*) AS p15,\n       COUNT(DISTINCT email)           / COUNT(*) AS full_sel\nFROM users;\n```\n\n一句话总结：**先把最终查询条件的组合区分度算出来，再决定建不建、几列、谁在前；区分度 < 0.01 的列不要单独建索引。**区分度只是快速筛选手段，`WHERE` 里高频出现的列、参与排序/分组/JOIN 的列即使区分度一般也值得建，最终以 `EXPLAIN` 和实测为准。\n\n### 3.5 其他要点\n\n```sql\n-- 前缀索引：长字符串列（前缀长度按区分度挑，见 3.4；注意不能用于覆盖索引和 ORDER BY）\nALTER TABLE users ADD INDEX idx_email (email(20));\n\n-- 8.0：函数索引 / 降序索引\nALTER TABLE orders ADD INDEX idx_date ((DATE(created_at)));\nALTER TABLE orders ADD INDEX idx_time_desc (created_at DESC);\n\n-- 8.0：先设为不可见，观察一段时间再决定是否真删（比直接 DROP 安全得多）\nALTER TABLE orders ALTER INDEX idx_old INVISIBLE;\nALTER TABLE orders DROP INDEX idx_old;\n\n-- 找冗余索引 / 没被用过的索引\nSELECT * FROM sys.schema_redundant_indexes;\nSELECT * FROM sys.schema_unused_indexes;\n```\n\n索引不是越多越好：每个索引都会让写入变慢、占用磁盘和 buffer pool。写多的表尽量控制在 3～5 个以内。\n\n---\n\n## 4. 索引失效的常见写法\n\n| 问题写法 | 为什么失效 | 改写 |\n| --- | --- | --- |\n| `WHERE DATE(created_at) = '2026-01-01'` | 索引列上用了函数 | `WHERE created_at >= '2026-01-01' AND created_at < '2026-01-02'` |\n| `WHERE phone = 13800000000`（`phone` 是 varchar） | 隐式类型转换，列被转成数字 | `WHERE phone = '13800000000'` |\n| `WHERE name LIKE '%张%'` | 前导 `%` 无法定位 | `LIKE '张%'`；中间匹配用全文索引 / ES |\n| `WHERE id + 1 = 100` | 索引列参与运算 | `WHERE id = 99` |\n| `WHERE a = 1 OR b = 2` | 两个不同列，可能退化成全表 | 分别建索引；或拆成 `UNION ALL` |\n| `WHERE status != 3` | 不等值通常用不上索引 | 改成枚举可用值 `IN (...)` |\n| `WHERE a = 1 ORDER BY b` 但索引是 `(b, a)` | 排序不符合最左前缀 | 建 `(a, b)` |\n| `ON t1.code = t2.code` 但两表字符集不同 | 无法使用索引比较 | 统一字符集与排序规则（都上 utf8mb4） |\n| `SELECT * FROM t WHERE ...` | 无法覆盖索引，必然回表 | 只查需要的列 |\n\n注意反向的隐式转换是**没问题**的：`int` 列与字符串比较时（`WHERE id = '123'`）是常量被转成数字，索引依然可用。\n\n---\n\n## 5. 查询改写\n\n```sql\n-- 1) 不要 SELECT *，只取需要的列，才有机会走覆盖索引\n-- ✗\nSELECT * FROM orders WHERE user_id = 123;\n-- ✓\nSELECT id, amount, created_at FROM orders WHERE user_id = 123;\n\n-- 2) COUNT：InnoDB 中 COUNT(*) 和 COUNT(1) 效率基本一致，COUNT(col) 会跳过 NULL\n--    ✗ 已废弃的 SQL_CALC_FOUND_ROWS 会扫全表\nSELECT SQL_CALC_FOUND_ROWS id FROM orders LIMIT 20;\n-- ✓ 需要总数就单独 COUNT，并且尽量加 WHERE 缩小范围\nSELECT COUNT(*) FROM orders WHERE user_id = 123;\n\n-- 3) 子查询 → JOIN（派生表无法用索引时会物化成临时表）\n-- ✗\nSELECT * FROM orders WHERE user_id IN (SELECT id FROM users WHERE vip = 1);\n-- ✓\nSELECT o.* FROM orders o JOIN users u ON u.id = o.user_id AND u.vip = 1;\n\n-- 4) UNION → UNION ALL（除非确实需要去重，UNION 会带来额外排序）\nSELECT id FROM orders WHERE status = 1\nUNION ALL\nSELECT id FROM orders WHERE status = 2;\n\n-- 5) 只需要判断存在性时加 LIMIT 1\nSELECT 1 FROM orders WHERE user_id = 123 LIMIT 1;\n\n-- 6) 批量操作合并成一条，避免 N 次往返\nINSERT INTO logs (user_id, action) VALUES (1,'a'), (2,'b'), (3,'c');\nSELECT id, name FROM users WHERE id IN (1, 2, 3);\n```\n\n---\n\n## 6. 深分页优化\n\n```sql\n-- ✗ 慢：要先扫描并丢弃 100 万行\nSELECT id, amount FROM orders ORDER BY id LIMIT 1000000, 20;\n\n-- ✓ 方案一：延迟关联，子查询只查主键（可走覆盖索引），再回表取需要的列\nSELECT o.id, o.amount\nFROM orders o\nJOIN (SELECT id FROM orders ORDER BY id LIMIT 1000000, 20) AS t ON t.id = o.id;\n\n-- ✓ 方案二：记住上一页最后一条的 id（游标分页，最推荐，但只能顺序翻页）\nSELECT id, amount FROM orders WHERE id > 1000000 ORDER BY id LIMIT 20;\n```\n\n业务上「跳到第 10 万页」几乎没人用，前端限制最大页数（比如 100 页）往往比 SQL 优化更有效。\n\n---\n\n## 7. JOIN、排序与分组\n\n```sql\n-- 1) 小表驱动大表：让行数少的表做驱动表，被驱动表的关联字段必须有索引\n--    优化器一般会自己判断，但关联字段没索引时会走 join buffer，性能直线下降\nEXPLAIN SELECT o.id, u.name\nFROM orders o JOIN users u ON u.id = o.user_id   -- users.id 是主键 ✓\nWHERE o.created_at >= '2026-01-01';\n\n-- 2) 排序：ORDER BY 的列顺序、方向要和索引一致才能免排序\n--    Extra 里出现 Using filesort 就说明要额外排序\nALTER TABLE orders ADD INDEX idx_user_time (user_id, created_at);\nSELECT id, created_at FROM orders WHERE user_id = 123 ORDER BY created_at DESC;\n-- 单列排序方向相反时可以利用索引反向扫描；多列混合 ASC/DESC 需要 8.0 的降序索引\n\n-- 3) 分组：GROUP BY 的列有索引可以避免 Using temporary\nSELECT status, COUNT(*) FROM orders WHERE user_id = 123 GROUP BY status;\n\n-- 4) 关联表数量别太多：一般不超过 3～4 张，join_buffer_size 调大能缓解但不能治本\n```\n\n---\n\n## 8. 表结构与数据类型\n\n- **够用就好**：能 `INT` 不用 `BIGINT`，能 `TINYINT` 不用 `INT`；金额用 `DECIMAL` 而不是 `FLOAT`。\n- **尽量 NOT NULL + 默认值**：NULL 会让索引和统计信息更复杂，`COUNT(col)` 也会漏掉。\n- **主键自增（或趋势递增）**：随机主键（如 UUID 字符串）会频繁触发页分裂；必须用 UUID 时存 `BINARY(16)`，8.0 可用 `UUID_TO_BIN(uuid, 1)` 把时间高位前置。\n- **大字段分离**：`TEXT` / `BLOB` 放到独立的扩展表，主表保持窄，一个数据页能放更多行。\n- **枚举适度**：状态类字段用 `TINYINT` + 注释，不要用长字符串。\n- **大表 DDL 要在线做**：用 `pt-online-schema-change` / `gh-ost`，或至少确认 `ALGORITHM=INPLACE, LOCK=NONE`：\n\n```sql\nALTER TABLE orders ADD INDEX idx_x (user_id), ALGORITHM=INPLACE, LOCK=NONE;\n```\n\n- **统计信息过期会导致选错索引**：\n\n```sql\nANALYZE TABLE orders;\n-- 8.0.3+：还可以给区分度不规则的列建直方图\nANALYZE TABLE orders UPDATE HISTOGRAM ON status, city WITH 64 BUCKETS;\n```\n\n---\n\n## 9. 写入优化与关键参数\n\n```sql\n-- 批量插入，控制在几百到一千行一批；避免一个事务里几万行\nINSERT INTO logs (user_id, action, created_at) VALUES\n(1, 'login', NOW()), (2, 'logout', NOW()), ...;\n\n-- 大批量导入：关掉自动提交 + 唯一性校验（确认数据可靠时）\nSET autocommit = 0;\nSET unique_checks = 0;\nSET foreign_key_checks = 0;\n-- ... LOAD DATA / INSERT ...\nCOMMIT;\n```\n\n| 参数 | 建议 | 说明 |\n| --- | --- | --- |\n| `innodb_buffer_pool_size` | 物理内存的 50%～70% | 最重要的参数，热数据要能全放进内存 |\n| `innodb_flush_log_at_trx_commit` | `1`（安全）/ `2`（快） | `1` 每次提交刷盘不丢数据；`2` 可能丢最近 1 秒事务 |\n| `sync_binlog` | `1`（安全）/ `0` 或 `100`（快） | 与上一条合称\"双 1\"，金融类业务不要动 |\n| `innodb_log_file_size` | 1～2 GB | 太小会频繁 checkpoint |\n| `binlog_group_commit_sync_delay` | 微秒 | 组提交，适度调大能提升高并发写入吞吐 |\n| `max_connections` | 按实际并发 | 盲调大只会让 CPU 排队更严重 |\n\n主从延迟的常见原因：大事务、单线程回放（可开并行复制 `slave_parallel_workers`）、从库上有大查询。**写入优化的一半是避免大事务。**\n\n---\n\n## 10. 实战案例：4.8s → 12ms\n\n**慢 SQL**（订单列表，`orders` 表 1200 万行）：\n\n```sql\nSELECT id, amount, created_at\nFROM orders\nWHERE user_id = 8848 AND status = 3\nORDER BY created_at DESC\nLIMIT 20;\n```\n\n**优化前**：表上只有主键。\n\n```\ntype: ALL   key: NULL   rows: 11984213   Extra: Using where; Using filesort\n```\n\n耗时 4.8s —— 全表扫描 + 额外排序。\n\n**第一步：加联合索引**\n\n```sql\nALTER TABLE orders ADD INDEX idx_user_status_time (user_id, status, created_at);\n```\n\n```\ntype: ref   key: idx_user_status_time   key_len: 12   rows: 236\nExtra: Using where\n```\n\n耗时降到 **12ms**：`user_id`、`status` 精确定位，`created_at` 顺带完成排序，`filesort` 消失。\n\n**第二步（可选）：如果这条 SQL QPS 很高，再做覆盖索引**\n\n```sql\nALTER TABLE orders ADD INDEX idx_cover (user_id, status, created_at, amount);\n-- Extra: Using where; Using index  ← 完全不回表\n```\n\n代价是索引多占空间、写入稍慢，要用压测数据决定是否值得。\n\n**要点**：`key_len: 12` 说明三列都用上了（`INT` 4 字节 + `TINYINT` 1 字节 …… 具体字节数取决于列类型和是否允许 NULL），这比 `rows` 更能反映索引的实际使用情况。\n\n---\n\n## 11. 上线前检查清单\n\n- [ ] 慢查询日志里没有新增慢 SQL；核心接口压测过 P99\n- [ ] 每条核心 SQL 都看过 `EXPLAIN`（8.0.18+ 尽量用 `EXPLAIN ANALYZE` 看实际行数）\n- [ ] `type` 至少 `range`，大表上没有 `ALL`\n- [ ] 没有 `SELECT *`、没有隐式类型转换、没有在索引列上做函数运算\n- [ ] 深分页已处理（游标分页或延迟关联）\n- [ ] 新加的索引在 `sys.schema_redundant_indexes` 里没有重复项\n- [ ] 新索引的列算过区分度：区分度 < 0.01 的列没有单独建索引，联合索引里区分度高的等值列在前（见 3.4）\n- [ ] 大表 DDL 用了在线工具或 `ALGORITHM=INPLACE, LOCK=NONE`\n- [ ] `ANALYZE TABLE` 更新过统计信息\n- [ ] 删除索引前先 `INVISIBLE` 观察一段时间\n- [ ] 上线后观察慢查询趋势、`threads_running`、主从延迟\n\n---\n\n## 12. 容易踩的认知误区\n\n1. **`rows` 是估算值**，不是实际扫描行数；差一个数量级很常见，要看真实情况用 `EXPLAIN ANALYZE`（8.0.18+）或 `Handler_read_*` 状态值。\n2. **有索引 ≠ 会走索引**。优化器按成本估算选择，区分度低、范围过大时它会主动放弃索引，这时要反思索引设计而不是硬加 `FORCE INDEX`。\n3. **`Using filesort` 不一定慢**。几十行的结果集排序毫无压力；真正的问题是大表 + 大结果集的排序。\n4. **`Using temporary` 多半来自 `GROUP BY` / `DISTINCT` / `UNION`**，未必致命，但值得看一眼能不能用索引消除。\n5. **`LIMIT` 不会减少扫描行数**（除非排序字段有索引，能顺序扫描后提前结束）。\n6. **加索引能救读，但会拖慢写**。写多读少的表，宁可让查询稍微慢一点。\n7. **不要在没有监控的情况下删索引**。先 `INVISIBLE`，跑一个业务周期再删。\n8. **版本差异要记住**：`hash join`（8.0.18+）、函数索引（8.0.13+）、降序索引（8.0）、`EXPLAIN ANALYZE`（8.0.18+）、不可见索引（8.0）在 5.7 上都不可用，写方案前先确认线上版本。\n\n```sql\nSELECT VERSION();\n```"},oNwx:function(n,r){n.exports="# MySQL 事务隔离级别详解\n\n> MySQL 中的“隔离模式”通常指 **事务隔离级别（Transaction Isolation Level）**。\n> 它用于解决多个事务并发执行时产生的 **脏读、不可重复读、幻读** 等问题，本质是在 **数据一致性** 和 **并发性能** 之间做权衡。\n\n## 目录\n\n- [1. 并发事务常见问题](#1-并发事务常见问题)\n- [2. MySQL 四种事务隔离级别](#2-mysql-四种事务隔离级别)\n- [3. 每种隔离级别解决什么问题](#3-每种隔离级别解决什么问题)\n  - [3.1 READ UNCOMMITTED](#31-read-uncommitted)\n  - [3.2 READ COMMITTED](#32-read-committed)\n  - [3.3 REPEATABLE READ](#33-repeatable-read)\n  - [3.4 SERIALIZABLE](#34-serializable)\n- [4. MySQL InnoDB 的实现机制](#4-mysql-innodb-的实现机制)\n- [5. 查看和设置隔离级别](#5-查看和设置隔离级别)\n- [6. 实际使用建议](#6-实际使用建议)\n- [7. 总结](#7-总结)\n\n## 1. 并发事务常见问题\n\n| 问题 | 含义 |\n|---|---|\n| 脏读 | 事务 A 读到了事务 B **未提交** 的数据，B 回滚后 A 读到的就是脏数据 |\n| 不可重复读 | 同一事务内两次读同一行，结果不同，因为其他事务提交了修改 |\n| 幻读 | 同一事务内两次执行相同范围查询，结果集行数不同，因为其他事务插入/删除了数据 |\n| 丢失更新 | 两个事务同时更新同一行，后提交的覆盖了先提交的，通常用锁或版本号解决 |\n\n## 2. MySQL 四种事务隔离级别\n\n| 隔离级别 | 脏读 | 不可重复读 | 幻读 | 说明 |\n|---|---|---|---|---|\n| READ UNCOMMITTED 读未提交 | 可能 | 可能 | 可能 | 几乎不用，能读到未提交数据 |\n| READ COMMITTED 读已提交 | 解决 | 可能 | 可能 | Oracle、PostgreSQL 默认；互联网高并发常用 |\n| REPEATABLE READ 可重复读 | 解决 | 解决 | InnoDB 基本解决 | **MySQL 默认** |\n| SERIALIZABLE 串行化 | 解决 | 解决 | 解决 | 全部加锁串行执行，并发最差 |\n\n## 3. 每种隔离级别解决什么问题\n\n### 3.1 READ UNCOMMITTED\n\n- 最低级别。\n- 事务可以读到其他事务未提交的数据。\n- 什么问题都不解决，基本不用。\n\n### 3.2 READ COMMITTED\n\n- 只能读到其他事务 **已提交** 的数据。\n- 解决：**脏读**。\n- 未解决：**不可重复读、幻读**。\n- 实现：每次 `SELECT` 都生成新的 Read View，所以能看到最新提交。\n- 特点：并发较好，但同一事务内多次读可能不一致。\n\n### 3.3 REPEATABLE READ\n\n- MySQL InnoDB 默认级别。\n- 解决：**脏读、不可重复读**。\n- 幻读：\n  - **快照读**：通过 MVCC 保证同一事务内读到的数据版本一致，不会幻读。\n  - **当前读**：如 `SELECT ... FOR UPDATE`、`UPDATE`、`DELETE`，通过 **Next-Key Lock（临键锁 = 记录锁 + 间隙锁）** 阻止其他事务插入，基本解决幻读。\n- 实现：事务第一次 `SELECT` 时生成 Read View，之后复用。\n- 代价：间隙锁容易导致死锁，并发不如 RC。\n\n### 3.4 SERIALIZABLE\n\n- 最高级别。\n- 读加共享锁，写加排他锁，事务串行执行。\n- 解决：**脏读、不可重复读、幻读**。\n- 代价：并发性能极差，一般只用于强一致、低并发场景。\n\n## 4. MySQL InnoDB 的实现机制\n\n### 4.1 MVCC（多版本并发控制）\n\n- 通过 undo log + Read View 实现一致性读。\n- RC：每次 `SELECT` 新建 Read View。\n- RR：第一次 `SELECT` 建 Read View，后续复用。\n\n### 4.2 Next-Key Lock\n\n- 记录锁 + 间隙锁。\n- RR 下用于防止当前读幻读。\n- RC 下一般只加记录锁，不加间隙锁，所以 RC 可能有幻读。\n\n### 4.3 间隙锁\n\n- 锁住索引记录之间的间隙，防止插入。\n- 只在 RR 及以下部分场景使用。\n\n## 5. 查看和设置隔离级别\n\n查看：\n\n```sql\nSELECT @@transaction_isolation;\n-- MySQL 5.7 可能是：\nSELECT @@tx_isolation;\n```\n\n设置会话级别：\n\n```sql\nSET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;\nSET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;\n```\n\n设置全局级别：\n\n```sql\nSET GLOBAL TRANSACTION ISOLATION LEVEL READ COMMITTED;\n```\n\n配置文件：\n\n```ini\n[mysqld]\ntransaction-isolation = READ-COMMITTED\n```\n\n## 6. 实际使用建议\n\n- **默认用 REPEATABLE READ**：MySQL 默认，数据一致性较好。\n- **高并发互联网业务常用 READ COMMITTED**：\n  - 减少间隙锁，降低死锁概率。\n  - 提高并发。\n  - 但需要配合 `binlog_format=ROW`，否则 statement 格式可能导致主从不一致。\n- **金融、强一致场景**：\n  - 可用 RR，必要时用 `SELECT ... FOR UPDATE`。\n  - 串行化性能太差，慎用。\n- **丢失更新**：\n  - 隔离级别不直接解决。\n  - 用乐观锁（版本号）或悲观锁（`FOR UPDATE`）解决。\n\n## 7. 总结\n\nMySQL 的四种事务隔离级别，本质是在 **数据一致性** 和 **并发性能** 之间做权衡：\n\n- 读未提交：什么都不解决。\n- 读已提交：解决脏读。\n- 可重复读：解决脏读、不可重复读，InnoDB 下基本解决幻读。\n- 串行化：全部解决，但性能最差。\n\n生产上：**MySQL 默认 RR；互联网高并发常用 RC + ROW binlog；强一致场景用 RR 或加锁。**"},pqdb:function(n,r){n.exports="# MySQL 8.0 CTE 使用指引\n\n> 适用范围：MySQL 8.0+。核心结论前置：**CTE 在 MySQL 中不是“天然的性能优化手段”，而是一把需要理解优化器行为才能正确使用的工具**。多处引用的 CTE 会被强制物化，单次引用的 CTE 大概率被内联——你的 SQL 写法和性能预期之间，隔着一层优化器的决策。\n\n---\n\n## 一、CTE 是什么\n\nCTE（Common Table Expression）用 `WITH` 子句定义一个**临时的命名结果集**，可以在同一语句的后续部分多次引用。它的主要价值是**提升可读性**和**避免重复书写子查询**，而不是保证性能提升。\n\n```sql\nWITH target_orders AS (\n    SELECT order_id, owner_id, order_paid_at, currency_rate\n    FROM platform_order\n    WHERE order_paid_at >= '2026-09-01 08:00:00'\n      AND order_paid_at <  '2026-09-02 08:00:00'\n      AND owner_id > 0\n)\nSELECT owner_id, COUNT(*) AS cnt\nFROM target_orders\nGROUP BY owner_id;\n```\n\n**递归 CTE** 用于层级数据（组织架构、评论树等），需要 `WITH RECURSIVE`，且**总是物化**：\n\n```sql\nWITH RECURSIVE cte (n) AS (\n    SELECT 1\n    UNION ALL\n    SELECT n + 1 FROM cte WHERE n < 5\n)\nSELECT * FROM cte;\n```\n\n---\n\n## 二、优化器的两种策略：Merge 与 Materialize\n\nMySQL 优化器对 CTE（以及派生表、视图引用）有两种处理方式，理解它们是正确使用 CTE 的前提。\n\n| 策略 | 行为 | 对性能的影响 |\n|---|---|---|\n| **Merge（内联）** | 把 CTE 定义**展开**到每个引用位置，当作普通子查询合并进外层查询 | 不产生临时表开销；但**每个引用位置都会重新执行一次 CTE 内部的查询** |\n| **Materialize（物化）** | 把 CTE 结果**计算一次**，写入内部临时表，所有引用都读这个临时表 | 源表只扫一次；但**产生临时表写入 + 后续读取的开销**，大结果集可能落盘 |\n\n关键原则：**优化器默认尽量避免物化**，因为物化有成本，而 merge 有时能让条件更好地下推到基表。\n\n---\n\n## 三、何时物化，何时内联\n\n这是 CTE 性能判断的核心。规则可以概括为：\n\n### 3.1 多次引用 → 强制物化\n\n**只要 CTE 在语句中被引用多次，MySQL 就会物化它**，且**每个语句只物化一次**，不论引用多少次。\n\n这意味着：\n\n- 源表（如 `platform_order`）**只被扫描一次**的预期，在多次引用场景下**理论上成立**；\n- 但代价是**临时表物化**，且物化结果**可能自动建索引**（见 3.3）。\n\n### 3.2 单次引用 → 大概率内联\n\n对于**只被引用一次**的非递归 CTE，优化器**默认倾向 merge（内联）**，而不是物化。\n\n单次引用时，内联通常更优：没有临时表开销，且外层条件可以下推到基表。**但内联意味着“CTE 内部的查询会被执行”，与物化“只执行一次”的直觉相反**——不过因为只引用一次，执行一次和内联展开在结果上是等价的，只是执行计划形态不同。\n\n### 3.3 物化后的自动索引\n\n如果 CTE 被物化，优化器会**自动评估并添加索引**到临时表上，以加速外层语句对它的访问。多次引用时，**可能为不同的引用分别创建不同的索引**。\n\n这是物化 CTE 相比手动临时表的一个隐性优势：不需要你显式 `CREATE INDEX`，优化器会根据访问方式自动决定。\n\n---\n\n## 四、如何验证：EXPLAIN 是唯一可靠依据\n\n**不能从 SQL 写法直接推断 CTE 是否物化，必须看 EXPLAIN。** 推荐使用树形格式，物化节点会显式出现：\n\n```sql\nEXPLAIN FORMAT=TREE\nWITH target_orders AS (...)\nSELECT ...;\n```\n\n在输出中关注：\n\n| 信号 | 含义 |\n|---|---|\n| `-> Materialize CTE <name> ...` | CTE 被物化 |\n| 出现 `creating_tmp_table` / `reusing_tmp_table`（optimizer trace） | 物化发生，且被复用 |\n| **完全没有 `<materialized>` / `Materialize` 节点** | CTE 被内联（merge） |\n| `type=ALL` 且 `rows` 接近基表行数 | 某个表被全表扫描，需要进一步排查索引 |\n\n**传统格式的局限**：传统 `EXPLAIN` 输出对 CTE 物化的展示不如 `FORMAT=TREE` 直观，容易误判。排查 CTE 性能问题时，**优先用 `EXPLAIN FORMAT=TREE`**；如果需要实际执行耗时，用 `EXPLAIN ANALYZE FORMAT=TREE`（注意：某些版本对 CTE 的 profiling 数据可能不完整）。\n\n---\n\n## 五、性能决策框架\n\n### 5.1 先问两个问题\n\n1. **CTE 被引用了几次？**\n  - 单次 → 优化器大概率内联，CTE 主要起可读性作用，**不要指望它“缓存结果”**。\n  - 多次 → 强制物化，源表只扫一次，但**承担临时表开销**。\n\n2. **CTE 的结果集有多大？**\n  - 小结果集（几千行以内）→ 物化临时表通常在内存中，开销可接受。\n  - 大结果集（百万行级别）→ 物化可能落盘，**多次引用的 CTE 未必比“两次走索引的 joinSub”更快**。\n\n### 5.2 多次引用 CTE 的典型陷阱\n\n你以为：\n\n> “CTE 被引用两次，所以 `platform_order` 只扫一次，性能一定比扫两次好。”\n\n实际可能：\n\n> CTE 被内联了（如果优化器判定 merge 更优，而没有被“多次引用强制物化”规则覆盖），`platform_order` **仍然被扫两次**；或者 CTE 被物化了，但物化临时表的写入成本超过了你节省的那一次索引扫描。\n\n**判断依据只能是 EXPLAIN**：如果 `EXPLAIN FORMAT=TREE` 里**没有 Materialize 节点**，说明 CTE 被内联，“只扫一次”的假设不成立。\n\n### 5.3 当你需要强制物化\n\nMySQL 提供 **`NO_MERGE` hint** 来阻止内联：\n\n```sql\nWITH target_orders AS (\n    SELECT ...\n)\nSELECT /*+ NO_MERGE(target_orders) */ ...\nFROM target_orders AS o\nJOIN target_orders AS t ON ...;\n```\n\n或通过会话级开关关闭 merging：\n\n```sql\nSET optimizer_switch = 'derived_merge=off';\n```\n\n**但这不是“优化”，而是“干预”**：强制物化意味着你确认了物化临时表的成本低于重复扫描，这需要 benchmark 支撑，不要凭直觉使用。\n\n### 5.4 替代方案：显式临时表\n\n如果 CTE 被多次引用、数据量大、且需要**显式索引控制**，可以考虑 `CREATE TEMPORARY TABLE`：\n\n```sql\nCREATE TEMPORARY TABLE tmp_target_orders AS\nSELECT ... FROM platform_order WHERE ...;\n\nALTER TABLE tmp_target_orders ADD INDEX (order_id);\n\n-- 后续 JOIN 使用 tmp_target_orders\n```\n\n临时表的优势是**索引完全可控**，劣势是**需要管理生命周期**（同一连接内有效），在连接池环境下**风险较高**（事务或多次查询可能切换连接）。\n\n---\n\n## 六、Hyperf / Query Builder 下的 CTE 注意事项\n\n### 6.1 `with()` 不是 CTE\n\nHyperf 的 **Eloquent 模型 Builder** 上的 `with()` 是**预加载关联**，不是 CTE。Query Builder（`Db::table()`）上也不保证有标准的 CTE 方法。如果你的 Hyperf 版本提供 `withExpression`，需要**先验证它生成的 SQL 和绑定顺序**，不能假设语义与原生 `WITH` 一致。\n\n### 6.2 绑定参数顺序是隐性炸弹\n\nHyperf 的 Query Builder 将绑定参数**按子句分类存储**（`select`、`from`、`join`、`where`、`having` 等）。当 CTE + `insertUsing` 组合时，如果 CTE 的绑定参数不在默认顺序（`select → from → join → where → ...`）的预期位置上，**SQL 中的 `?` 占位符顺序可能与 `getBindings()` 返回的数组顺序不一致**，导致参数错位或数量不匹配。\n\n**验证方法**：在开发环境打印 `$query->toSql()` 和 `$query->getBindings()`，逐个对照 `?` 的出现顺序是否与绑定数组一致。\n\n### 6.3 推荐：CTE 逻辑用原生 SQL 或 `withExpression` + 严格验证\n\n如果 CTE 是性能关键路径，**优先写原生 SQL** 并通过 `Db::select($sql, $bindings)` 执行，避免 Builder 层对 CTE 的封装不完整带来的不确定性。如果使用 `withExpression`，必须做 6.2 的绑定顺序验证。\n\n---\n\n## 七、最佳实践清单\n\n**✅ 适合用 CTE 的场景**\n\n- 同一子查询**需要被多次引用**，且结果集**不大**（物化临时表在内存中）；\n- 递归层级查询（必须用 CTE）；\n- 需要提升 SQL **可读性**，且性能已通过 EXPLAIN 验证无退化。\n\n**⚠️ 需要验证后再用的场景**\n\n- 单次引用的 CTE：默认会被内联，**不要指望“物化缓存”**；\n- 多次引用 + 大结果集：**必须对比** CTE 物化 vs `joinSub` 两次索引扫描 vs 临时表的实际耗时；\n- `INSERT ... SELECT` 中嵌套 CTE：额外检查绑定参数顺序。\n\n**❌ 不应依赖的行为**\n\n- 不能假设“写了 CTE 就一定会物化”；\n- 不能假设“CTE 被引用 N 次就一定只执行一次内部查询”（内联时每个引用独立执行）；\n- 不能假设“CTE 物化后自动有最优索引”（优化器自动索引是启发式的，不保证覆盖所有访问路径）。\n\n**🛠️ 上线前必做**\n\n1. 对目标 SQL 跑 `EXPLAIN FORMAT=TREE`，确认关键表的 `type` 不是 `ALL`（或 `ALL` 仅出现在确实需要全表扫描的小表上）；\n2. 确认 `platform_order_product.order_id` 等 JOIN 列上有索引；\n3. 用真实数据量级 benchmark，对比 CTE 方案与替代方案（`joinSub` / 临时表）的**实际耗时**，而非仅看 EXPLAIN 估算；\n4. 如果在 Hyperf 中使用 CTE，验证 `toSql()` 与 `getBindings()` 的占位符顺序一致。"}});
